// ==================================================
// Post service
// ==================================================

import { randomUUID } from "node:crypto";
import * as postRepository from "../repositories/postRepository.mjs";
import { ForbiddenError, NotFoundError } from "../utils/errors.mjs";
import { generateGuestUsername } from "../utils/guestUsername.mjs";

// Post ids are generated by randomUUID(), always lowercase v4. Anything else cannot exist.
const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

// The one ownership rule, shared by update and delete. Throws 403 if the user does not own the post.
// Guest posts have no owner: a registered user with the same name as a guest must not take them over.
const assertOwner = (post, user) => {
  if (post.isGuest) {
    throw new ForbiddenError("Guest posts cannot be changed");
  }

  if (post.username !== user.username) {
    throw new ForbiddenError("You can only change your own posts");
  }
};

// Creates a post. A logged-in user owns it with isGuest false. Without a user it becomes
// a guest post with a generated name and isGuest true. The client only decides title and content.
export const createPost = async ({ title, content }, user) => {
  const now = new Date().toISOString();

  return postRepository.createPost({
    id: randomUUID(),
    username: user ? user.username : generateGuestUsername(),
    isGuest: !user,
    title,
    content,
    createdAt: now,
    updatedAt: now,
  });
};

// All posts, or only one user's posts when username is given. Both come newest first from the repository.
export const getPosts = ({ username } = {}) =>
  username
    ? postRepository.getPostsByUsername(username)
    : postRepository.getAllPosts();

// One post by id. Throws 404 if it does not exist. Reused by update, delete and comments.
export const getPost = async (postId) => {
  const post = UUID_PATTERN.test(postId)
    ? await postRepository.getPostById(postId)
    : null;

  if (!post) {
    throw new NotFoundError("Post not found");
  }

  return post;
};

// Updates title and content of the user's own post. Throws 404 if it does not exist and 403 if the user is not the owner.
export const updatePost = async (postId, { title, content }, user) => {
  const post = await getPost(postId);
  assertOwner(post, user);

  const updated = await postRepository.updatePost(postId, {
    title,
    content,
    updatedAt: new Date().toISOString(),
  });

  // The post was deleted between the ownership check and the update
  if (!updated) {
    throw new NotFoundError("Post not found");
  }

  return updated;
};

// Deletes the user's own post. Throws 404 if it does not exist and 403 if the user is not the owner.
export const deletePost = async (postId, user) => {
  const post = await getPost(postId);
  assertOwner(post, user);

  const deleted = await postRepository.deletePost(postId);

  // The post was deleted by another request between the ownership check and the delete
  if (!deleted) {
    throw new NotFoundError("Post not found");
  }
};
